INSERT INTO accommodation (id, host_id, name, description, type, region, address, address_detail, created_at, updated_at, deleted_at) VALUES
    (1, 21, '포레스트 리솜', '충북 제천시에 있는 리조트입니다. 여러 명이 함께 머물기 좋은 휴양형 숙소입니다.', 'RESORT', 'CHUNGBUK', '충청북도 제천시', '', @now - INTERVAL 608896 MINUTE, NULL, NULL),
    (2, 22, '르블랑 풀빌라', '전남 여수시에 있는 풀빌라입니다. 일행끼리 프라이빗하게 쉬어가기 좋은 숙소입니다.', 'POOL_VILLA', 'JEONNAM', '전라남도 여수시', '화정면 조발도길 30', @now - INTERVAL 612918 MINUTE, NULL, NULL),
    (3, 23, '광양 디바인 호텔', '전남 광양시에 있는 모텔입니다. 부담 없는 가격으로 하루 묵어가기 좋은 숙소입니다.', 'MOTEL', 'JEONNAM', '전라남도 광양시', '중동', @now - INTERVAL 640046 MINUTE, NULL, NULL),
    (4, 24, '스카리아풀빌라', '강원 강릉시에 있는 풀빌라입니다. 일행끼리 프라이빗하게 쉬어가기 좋은 숙소입니다.', 'POOL_VILLA', 'GANGWON', '강원특별자치도 강릉시', '난설헌로 261', @now - INTERVAL 691103 MINUTE, NULL, NULL),
    (5, 25, '생각속의집 펜션', '경기 양평군에 있는 펜션입니다. 가족, 친구와 함께 여유롭게 쉬어가기 좋은 숙소입니다.', 'PENSION', 'GYEONGGI', '경기도 양평군', '단월면 대부록길 37', @now - INTERVAL 617575 MINUTE, NULL, NULL),
