    (179, 31, '가야산 백운동 야영장', '경북 성주군에 있는 캠핑장입니다. 자연 속에서 야영을 즐길 수 있는 곳입니다.', 'CAMPING', 'GYEONGBUK', '경상북도 성주군', '', @now - INTERVAL 613302 MINUTE, NULL, NULL),
    (180, 32, '미타스야 료칸 호텔 by 아늑', '대전 유성구에 있는 모텔입니다. 부담 없는 가격으로 하루 묵어가기 좋은 숙소입니다.', 'MOTEL', 'DAEJEON', '대전광역시 유성구', '', @now - INTERVAL 674729 MINUTE, NULL, NULL);

